import{_ as e,o as a,c as o,aa as l}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/academy/img/zalozeni-stavby/10.webp",m=JSON.parse('{"title":"Zapnout úkoly na stavbě","description":"","frontmatter":{"title":"Zapnout úkoly na stavbě","wiki":"cs:tickets:new_project"},"headers":[],"relativePath":"tickets/new_project.md","filePath":"tickets/new_project.md","lastUpdated":1794209661000}'),r={name:"tickets/new_project.md"};function s(i,t,d,v,u,p){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="zapnout-ukoly-na-stavbe" tabindex="-1">Zapnout úkoly na stavbě <a class="header-anchor" href="#zapnout-ukoly-na-stavbe" aria-label="Permalink to &quot;Zapnout úkoly na stavbě&quot;">​</a></h1><p>Úkoly zadáváte jen na stavbě, která má zapnutý modul <strong>Management úkolů</strong>. Kromě toho nastavte projektový tým, výkresy a číselníky úkolů – teprve pak se s modulem dobře pracuje.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/zalozeni-stavby">Založit novou stavbu</a> a <a href="/buildary-help-preview/akademie/projektovy-tym">Přidat lidi a firmy do týmu stavby</a> v Akademii.</p><p>Jak stavbu založit a co všechno se v Nastavení stavby nastavuje, popisuje <a href="/buildary-help-preview/diary/projectsetup">Založit stavbu</a>. Na této stránce je jen to, co se týká úkolů.</p><h2 id="zapnout-modul" tabindex="-1">Zapnout modul <a class="header-anchor" href="#zapnout-modul" aria-label="Permalink to &quot;Zapnout modul&quot;">​</a></h2><ol><li>Otevřete <strong>Nastavení stavby</strong> (ikona ozubeného kola v levém panelu), záložku <strong>Stavba</strong>.</li><li>V části <strong>Používané moduly</strong> zaškrtněte <strong>Modul Management úkolů</strong>.</li><li>Klikněte na <strong>Uložit</strong>.</li></ol><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Část Používané moduly s volbou Modul Management úkolů ve formuláři stavby" loading="lazy"></figure><p>V levém panelu se pak pod stavbou objeví <strong>Management úkolů</strong> s položkami <strong>Dashboard</strong>, <strong>Seznam úkolů</strong>, <strong>Kanban úkolů</strong> a <strong>Výkresy a Mapa</strong>. Nevidíte-li je, modul na stavbě zapnutý není.</p><ul><li>Moduly mění ten, kdo má na stavbě kompetenci <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</li><li>Výchozí výběr modulů přebírá nová stavba z domény. Aspoň jeden modul musí zůstat zapnutý.</li><li>Modul ovlivňuje cenu stavby. Moduly můžete změnit kdykoli, ale nejvýš jednou za den. V doméně s individuálním režimem je měnit nemůžete. Podrobnosti viz <a href="/buildary-help-preview/diary/projectsetup#pouzivane-moduly">Založit stavbu</a>.</li><li>Vypnutím modulu zmizí úkoly z levého panelu.</li><li>Úkol k záznamu ve stavebním deníku založíte, jen když je modul zapnutý.</li></ul><h2 id="co-nastavit-pro-ukoly" tabindex="-1">Co nastavit pro úkoly <a class="header-anchor" href="#co-nastavit-pro-ukoly" aria-label="Permalink to &quot;Co nastavit pro úkoly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Co</th><th>Proč</th><th>Kde je popsáno</th></tr></thead><tbody><tr><td><strong>Projektový tým</strong></td><td>Řešitele a Schvalovatele vybíráte jen z členů projektového týmu. Přidejte do týmu všechny, kdo budou úkoly zadávat, řešit nebo schvalovat.</td><td><a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a></td></tr><tr><td><strong>Role členů</strong></td><td>Role určuje, zda člen smí zadávat nové úkoly a zda vidí všechny úkoly stavby.</td><td><a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a></td></tr><tr><td><strong>E-mailové oznámení - Management úkolů</strong></td><td>U každého člena nastavíte, zda a jak mu budou chodit e-maily o úkolech, které řeší nebo schvaluje.</td><td><a href="/buildary-help-preview/tickets/notification">Upozornění na úkoly</a></td></tr><tr><td><strong>Části stavby a výkresy</strong></td><td>Do výkresů umisťujete úkoly a podle částí stavby úkoly filtrujete.</td><td><a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a></td></tr><tr><td><strong>Číselníky - Management úkolů</strong></td><td>Kategorie úkolů, štítky a pravidla, která doplní Řešitele a Schvalovatele.</td><td><a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Nejdřív tým, pak úkoly</p><p>Chybí-li člověk v nabídce Řešitelů nebo Schvalovatelů, není v projektovém týmu stavby. Přidejte ho do týmu a pak ho u úkolu vyberte.</p></div>',12)])])}const y=e(r,[["render",s]]);export{m as __pageData,y as default};
